-- 303: 大和オハナ保育園の保育安全計画(令和8年度=2026年度)を、今年度の重要事項説明書の内容で穴埋め。
-- 既存があれば content 更新、なければ作成(idempotent)。掲示・添付・アプリ承認の土台。
do $$
declare v_tmpl uuid; v_id uuid; v_office uuid := '9503dfbd-6cdc-424c-aa3e-ac18441478ba'; v_year int := 2026;
begin
  select id into v_tmpl from guidance_plan_templates where plan_type='safety' and version=1;
  if v_tmpl is null then raise exception 'safety template not found (301未適用?)'; end if;
  select id into v_id from guidance_plans
    where office_id=v_office and plan_type='safety' and fiscal_year=v_year
      and class_id is null and month is null and week_start_date is null;
  if v_id is null then
    insert into guidance_plans (office_id, class_id, plan_type, age_variant, template_id, fiscal_year, content, status)
    values (v_office, null, 'safety', null, v_tmpl, v_year, '{"inspect_m4": "・防火設備\n・避難経路\n・緊急連絡先", "inspect_m5": "・遊具\n・散歩コース（散歩コース内の固定遊具を含む。）", "inspect_m6": "・プール用具の安全点検", "inspect_m7": "・園庭全体（内扉、フェンス、固定遊具、排水路等）\n・園舎全体（水道、トイレ、建付け、高所等）", "inspect_m8": "・加湿器\n・空気清浄機", "inspect_m9": "・台風対策（備蓄の確認等）", "inspect_m10": "園外保育の危険か所の点検\n園外保育での歩き方の指導", "inspect_m11": "・水まわり（冬季に向けた点検）", "inspect_m12": "・室内点検暖房の設定温度、室内換気", "inspect_m1": "・室内点検", "inspect_m2": "・通路（経路等）", "inspect_m3": "室内、室外遊具の安全点検", "daijiko_estab": "2025年12月1日", "daijiko_review": "2026年10月1日", "daijiko_place": "事務所内・更衣室", "m_nap_check": "○", "m_nap_estab": "2025年12月1日", "m_nap_review": "2026年10月1日", "m_nap_place": "各クラスiPad内・職員室PC", "m_meal_check": "○", "m_meal_estab": "2025年12月1日", "m_meal_review": "2026年10月1日", "m_meal_place": "各クラスiPad内・職員室PC", "m_pool_check": "○", "m_pool_estab": "2025年12月1日", "m_pool_review": "2026年10月1日", "m_pool_place": "事務所内・更衣室", "m_outdoor_check": "○", "m_outdoor_estab": "2025年12月1日", "m_outdoor_review": "2026年10月1日", "m_outdoor_place": "事務所内・各クラス内", "saigai_estab": "2025年12月1日", "saigai_review": "2026年10月1日", "saigai_place": "事務所内・更衣室", "t119_estab": "2025年12月1日", "t119_review": "2026年10月1日", "t119_place": "事務所内・更衣室", "kyukyu_estab": "2025年12月1日", "kyukyu_review": "2026年10月1日", "kyukyu_place": "事務所内・更衣室", "fushinsha_estab": "2025年12月1日", "fushinsha_review": "2026年10月1日", "fushinsha_place": "事務所内・更衣室", "infant_term1": "・交通安全教室\n横断歩道は「右左右」手を挙げて渡る。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n\n遊具遊びや散歩時の事故防止\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。", "infant_term2": "・熱中症対策\n水分補給・衣服の調節を行う\n・プール遊び時の事故防止\nプール活動ができる環境か\n・雨天、強風、雷が鳴ったとき\n・光化学スモッグ警報発令のとき\n・PM2.5の注意喚起のとき\n・暑さ（熱中症）指数が高いとき\n・土、砂等による汚染が著しいとき\n一つでも当てはまる場合は中止とする\n監視役と園児につく職員の役割を明確にする。\nプール遊び当日は、いつもより念入りに朝の視診を行う。\nプールに入れるとなっていても、実際に目で見て判断する。", "infant_term3": "・遊具遊びや散歩時の事故防止\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。", "infant_term4": "散歩時の歩き方指導\n冬休み中の安全で楽しい過ごし方\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。\n冬の感染症には注意する。", "over3_term1": "・交通安全教室\n列の最前と最後尾の距離を空けずに歩く。\n歩道から降りないように指導。保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n横断歩道を渡る際は、「右見て左見て右見る」手を挙げて渡ることを指導する。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。", "over3_term2": "・熱中症対策\n水分補給・衣服の調節を行う\n・プール遊び時の事故防止\nプール活動ができる環境か\n・雨天、強風、雷が鳴ったとき\n・光化学スモッグ警報発令のとき\n・PM2.5の注意喚起のとき\n・暑さ（熱中症）指数が高いとき\n・土、砂等による汚染が著しいとき\n一つでも当てはまる場合は中止とする\n早寝早起きをし朝ごはんをしっかり食べ、先生の話をよく聞き、お友だちを押したり走ったりしないようにする。", "over3_term3": "・遊具遊びや散歩時の事故防止\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。", "over3_term4": "散歩時の歩き方指導\n冬休み中の安全で楽しい過ごし方\nバス乗車の約束\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。\n知らない人についていかない\nバスの中では立ち歩かない。大声で話さない。", "guardian_term1": "・安全計画及び安全に関する取組の内容について、重要事項説明書として保護者に配布し、同意書を提出いただく。", "guardian_term2": "・園だより（クラスだより）を活用し、取組内容の周知を図る。", "guardian_term3": "・安全計画及び安全に関する取組の内容について、玄関ホールに掲示し、周知を図る。\n・園だより（クラスだより）を活用し、取組内容の周知を図る。", "guardian_term4": "・園だより（クラスだより）を活用し、取組内容の周知を図る。", "hinan_m4": "火災\n消火訓練\n避難訓練", "hinan_m5": "火災\n消火訓練\n避難訓練", "hinan_m6": "火災\n地震\n消火訓練\n避難訓練", "hinan_m7": "火災\n水害\n消火訓練\n避難訓練", "hinan_m8": "火災\n不審者訓練\n消火訓練\n避難訓練", "hinan_m9": "火災\n地震\n消火訓練\n避難訓練", "hinan_m10": "総合消防訓練\n地震\n消火訓練\n避難訓練", "hinan_m11": "火災\n消火訓練\n避難訓練", "hinan_m12": "火災\n不審者\n消火訓練\n避難訓練", "hinan_m1": "火災\n地震\n消火訓練\n避難訓練", "hinan_m2": "火災\n地震\n通報\n消火訓練\n避難訓練", "hinan_m3": "火災\n消火訓練\n避難訓練", "other_m4": "心肺蘇生法", "other_m6": "不審者訓練", "other_m8": "通報訓練", "other_m12": "不審者訓練", "other_m3": "通報訓練", "drill1_content": "消火訓練", "drill1_who": "訓練当日の出勤している職員", "staff_term1": "園外実施　保健安全研修\n園内実施　心肺蘇生", "staff_term2": "園内実施　心肺蘇生\n園外実施　障害児保育\n園外実施　乳児保育", "staff_term3": "園内実施　気道内異物除去", "staff_term4": "園外実施　保護者支援・子育て支援\n園外実施　幼児教育", "admin_schedule": "・救命講習1（事前学習必須・大和市消防本部で開催）\n・救命講習I（大和市消防本部で開催）", "prevention": "・ヒヤリハット事例の園内研修\n・人数の点呼確認の実地訓練", "other": "・登降園管理システムを活用した安全管理\n・警察や消防等、地域の関係者と連携し研修や講習をしていただく。"}'::jsonb, 'draft');
  else
    update guidance_plans set content='{"inspect_m4": "・防火設備\n・避難経路\n・緊急連絡先", "inspect_m5": "・遊具\n・散歩コース（散歩コース内の固定遊具を含む。）", "inspect_m6": "・プール用具の安全点検", "inspect_m7": "・園庭全体（内扉、フェンス、固定遊具、排水路等）\n・園舎全体（水道、トイレ、建付け、高所等）", "inspect_m8": "・加湿器\n・空気清浄機", "inspect_m9": "・台風対策（備蓄の確認等）", "inspect_m10": "園外保育の危険か所の点検\n園外保育での歩き方の指導", "inspect_m11": "・水まわり（冬季に向けた点検）", "inspect_m12": "・室内点検暖房の設定温度、室内換気", "inspect_m1": "・室内点検", "inspect_m2": "・通路（経路等）", "inspect_m3": "室内、室外遊具の安全点検", "daijiko_estab": "2025年12月1日", "daijiko_review": "2026年10月1日", "daijiko_place": "事務所内・更衣室", "m_nap_check": "○", "m_nap_estab": "2025年12月1日", "m_nap_review": "2026年10月1日", "m_nap_place": "各クラスiPad内・職員室PC", "m_meal_check": "○", "m_meal_estab": "2025年12月1日", "m_meal_review": "2026年10月1日", "m_meal_place": "各クラスiPad内・職員室PC", "m_pool_check": "○", "m_pool_estab": "2025年12月1日", "m_pool_review": "2026年10月1日", "m_pool_place": "事務所内・更衣室", "m_outdoor_check": "○", "m_outdoor_estab": "2025年12月1日", "m_outdoor_review": "2026年10月1日", "m_outdoor_place": "事務所内・各クラス内", "saigai_estab": "2025年12月1日", "saigai_review": "2026年10月1日", "saigai_place": "事務所内・更衣室", "t119_estab": "2025年12月1日", "t119_review": "2026年10月1日", "t119_place": "事務所内・更衣室", "kyukyu_estab": "2025年12月1日", "kyukyu_review": "2026年10月1日", "kyukyu_place": "事務所内・更衣室", "fushinsha_estab": "2025年12月1日", "fushinsha_review": "2026年10月1日", "fushinsha_place": "事務所内・更衣室", "infant_term1": "・交通安全教室\n横断歩道は「右左右」手を挙げて渡る。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n\n遊具遊びや散歩時の事故防止\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。", "infant_term2": "・熱中症対策\n水分補給・衣服の調節を行う\n・プール遊び時の事故防止\nプール活動ができる環境か\n・雨天、強風、雷が鳴ったとき\n・光化学スモッグ警報発令のとき\n・PM2.5の注意喚起のとき\n・暑さ（熱中症）指数が高いとき\n・土、砂等による汚染が著しいとき\n一つでも当てはまる場合は中止とする\n監視役と園児につく職員の役割を明確にする。\nプール遊び当日は、いつもより念入りに朝の視診を行う。\nプールに入れるとなっていても、実際に目で見て判断する。", "infant_term3": "・遊具遊びや散歩時の事故防止\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。", "infant_term4": "散歩時の歩き方指導\n冬休み中の安全で楽しい過ごし方\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。\n冬の感染症には注意する。", "over3_term1": "・交通安全教室\n列の最前と最後尾の距離を空けずに歩く。\n歩道から降りないように指導。保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n横断歩道を渡る際は、「右見て左見て右見る」手を挙げて渡ることを指導する。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。", "over3_term2": "・熱中症対策\n水分補給・衣服の調節を行う\n・プール遊び時の事故防止\nプール活動ができる環境か\n・雨天、強風、雷が鳴ったとき\n・光化学スモッグ警報発令のとき\n・PM2.5の注意喚起のとき\n・暑さ（熱中症）指数が高いとき\n・土、砂等による汚染が著しいとき\n一つでも当てはまる場合は中止とする\n早寝早起きをし朝ごはんをしっかり食べ、先生の話をよく聞き、お友だちを押したり走ったりしないようにする。", "over3_term3": "・遊具遊びや散歩時の事故防止\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。", "over3_term4": "散歩時の歩き方指導\n冬休み中の安全で楽しい過ごし方\nバス乗車の約束\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。\n知らない人についていかない\nバスの中では立ち歩かない。大声で話さない。", "guardian_term1": "・安全計画及び安全に関する取組の内容について、重要事項説明書として保護者に配布し、同意書を提出いただく。", "guardian_term2": "・園だより（クラスだより）を活用し、取組内容の周知を図る。", "guardian_term3": "・安全計画及び安全に関する取組の内容について、玄関ホールに掲示し、周知を図る。\n・園だより（クラスだより）を活用し、取組内容の周知を図る。", "guardian_term4": "・園だより（クラスだより）を活用し、取組内容の周知を図る。", "hinan_m4": "火災\n消火訓練\n避難訓練", "hinan_m5": "火災\n消火訓練\n避難訓練", "hinan_m6": "火災\n地震\n消火訓練\n避難訓練", "hinan_m7": "火災\n水害\n消火訓練\n避難訓練", "hinan_m8": "火災\n不審者訓練\n消火訓練\n避難訓練", "hinan_m9": "火災\n地震\n消火訓練\n避難訓練", "hinan_m10": "総合消防訓練\n地震\n消火訓練\n避難訓練", "hinan_m11": "火災\n消火訓練\n避難訓練", "hinan_m12": "火災\n不審者\n消火訓練\n避難訓練", "hinan_m1": "火災\n地震\n消火訓練\n避難訓練", "hinan_m2": "火災\n地震\n通報\n消火訓練\n避難訓練", "hinan_m3": "火災\n消火訓練\n避難訓練", "other_m4": "心肺蘇生法", "other_m6": "不審者訓練", "other_m8": "通報訓練", "other_m12": "不審者訓練", "other_m3": "通報訓練", "drill1_content": "消火訓練", "drill1_who": "訓練当日の出勤している職員", "staff_term1": "園外実施　保健安全研修\n園内実施　心肺蘇生", "staff_term2": "園内実施　心肺蘇生\n園外実施　障害児保育\n園外実施　乳児保育", "staff_term3": "園内実施　気道内異物除去", "staff_term4": "園外実施　保護者支援・子育て支援\n園外実施　幼児教育", "admin_schedule": "・救命講習1（事前学習必須・大和市消防本部で開催）\n・救命講習I（大和市消防本部で開催）", "prevention": "・ヒヤリハット事例の園内研修\n・人数の点呼確認の実地訓練", "other": "・登降園管理システムを活用した安全管理\n・警察や消防等、地域の関係者と連携し研修や講習をしていただく。"}'::jsonb where id=v_id;
  end if;
